//! Phase C review: valid code that `#[composable]` fails to compile.
//!
//! A `pub` composable's call macro is `#[macro_export]`ed at the crate root as
//! `__compose_call_{name}_{hash}`, the hash taken from the declaration's file, line, column and
//! name. Composables generated by a `macro_rules!` share the attribute's span (its file, line
//! and column in the macro), so two of the same name in different modules (`icons::filled::Add`
//! and `icons::outlined::Add`, made by one macro) get the same hidden name: E0428 "the name
//! `__compose_call_Leaf_…` is defined multiple times". The functions themselves are fine.
//!
//! Expected: compiles. Actual: E0428.

#![allow(non_snake_case, dead_code)]

macro_rules! leaf {
    ($name:ident) => {
        #[compose::runtime::composable]
        pub fn $name(x: u32) {
            let _ = x;
        }
    };
}

pub mod a {
    leaf!(Leaf);
}

pub mod b {
    leaf!(Leaf);
}

#[test]
fn compiles() {}
